// Runs the built plugin against a minimal mock of OpenRCT2's title screen API, using a
// playlist and script generated by tools/mksequence.py. Checks the player's behaviour
// (park changes, view order, hold, shuffle, speed, view fitting, sound fades), not OpenRCT2 itself.
//
// Usage: node test/mock-run.mjs <sequence dir> <playlist.json>
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import vm from "node:vm";

const [seqDir, playlistPath] = process.argv.slice(2);
const playlist = JSON.parse(fs.readFileSync(playlistPath, "utf8"));
// The playlist's views were judged in a 1920x1080 game window, the mock's; the window scaling
// test near the end plays them as judged in a larger one.
assert.deepEqual(playlist.screen, [1920, 1080], "the playlist names the window its views were judged in");
const parkFiles = fs.readdirSync(seqDir).filter(f => f.endsWith(".park")).sort();

// Parse script.txt into commands the way the plugin API exposes them.
const commands = [];
for (const raw of fs.readFileSync(path.join(seqDir, "script.txt"), "utf8").split("\n")) {
    const line = raw.split("#")[0].trim();
    if (!line) continue;
    const [op, ...args] = line.split(" ");
    if (op === "LOAD") commands.push({ type: "load", index: parkFiles.indexOf(args.join(" ")) });
    else commands.push({ type: op.toLowerCase() });
}

// Mock built-in player: executing a LOAD runs instant commands until the next WAIT.
const firstWaitAfter = i => { let j = i; while (commands[j].type !== "wait") j++; return j; };
const loads = [];
const fades = []; // fadeSounds calls
const sequence = {
    name: playlist.sequence,
    parks: parkFiles.map(fileName => ({ fileName })),
    commands,
    isPlaying: false,
    position: null,
    play() { this.isPlaying = true; this.position = firstWaitAfter(0); loads.push(commands[0].index); },
    seek(i) {
        assert.equal(commands[i].type, "load", "plugin should only seek to LOAD commands");
        this.position = firstWaitAfter(i); loads.push(commands[i].index);
        context.gameSpeed = 1; // loading a park resets the speed
    },
    fadeSounds(level, ms) { fades.push({ level, ms, loads: loads.length }); }, // patched engine
};

let now = 0;
const store = { RCTScreensaver: { playlist, settings: { debug: false, fadeMs: 0 } } };
const lookup = key => key.split(".").reduce((o, k) => (o == null ? undefined : o[k]), store);
const viewport = { rotation: 0, zoom: 0, centre: { x: 0, y: 0 },
    moveTo(c) { this.centre = c; }, getCentrePosition() { return this.centre; } };
const shortcuts = {};
const windows = []; // open windows
const openWindow = desc => {
    const w = { desc, close() { windows.splice(windows.indexOf(w), 1); desc.onClose?.(); },
        bringToFront() {}, widgets: {},
        findWidget(name) { return (this.widgets[name] ??= {}); } };
    windows.push(w);
    return w;
};
const intervals = []; // the player's update (100 ms) and the camera (every game tick)
const actions = {}; // custom actions registered by the plugin
const shows = []; // companion shows the plugin started
let plugin;
const logs = [];
const context = {
    mode: "title", gameSpeed: 1,
    sharedStorage: {
        get: (k, d) => lookup(k) ?? d,
        set: (k, v) => { const parts = k.split("."); const last = parts.pop();
            parts.reduce((o, p) => (o[p] ??= {}), store)[last] = v; },
    },
    getRandom: (min, max) => min + Math.floor(Math.random() * (max - min)),
    executeAction(name, args, cb) {
        if (name.startsWith("rctscreensaver-show-")) { shows.push(args.show); cb?.({}); return; }
        assert.equal(name, "gamesetspeed"); this.gameSpeed = args.speed; cb({});
    },
    registerAction(name, query, execute) { actions[name] = execute; },
    setInterval(fn, ms) { intervals.push({ fn, ms }); },
    subscribe(hook, fn) { if (hook === "interval.tick") tickHooks.push(fn); return { dispose() {} }; },
};
const tickHooks = []; // interval.tick: once per game tick
const sandbox = {
    context, map: { getTile: () => ({ elements: [{ type: "surface", baseZ: 48 }] }), getRide: () => null, getEntity: () => null },
    titleSequenceManager: { titleSequences: [sequence] },
    ui: { width: 1920, height: 1080, registerShortcut: d => { shortcuts[d.id] = d.callback; }, registerToolboxMenuItem() {}, openWindow,
          mainViewport: viewport },
    registerPlugin: p => { plugin = p; },
    console: { log: m => { logs.push(m); if (process.env.VERBOSE) process.stdout.write(m + "\n"); } },
    Date: class extends Date { static now() { return now; } },
};
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(new URL("../dist/rct-screensaver.js", import.meta.url), "utf8"), sandbox);
plugin.main();

// 100 ms of real time per step, in game ticks of 25 ms
const tick = (ms = 100) => {
    for (let t = 0; t < ms; t += 100) {
        for (let i = 0; i < 4; i++) { now += 25; tickHooks.forEach(fn => fn()); intervals.filter(v => v.ms < 100).forEach(v => v.fn()); }
        intervals.filter(v => v.ms >= 100).forEach(v => v.fn());
    }
};
const key = id => shortcuts[`rctscreensaver.${id}`]();
const tileOf = () => [Math.round((viewport.centre.x - 16) / 32), Math.round((viewport.centre.y - 16) / 32)];
const expectView = (p, v) => {
    const view = playlist.parks[p].views[v];
    assert.deepEqual(tileOf(), [view.x, view.y], `park ${p} view ${v}`);
    assert.equal(viewport.rotation, view.rotation);
};

// View fitting is checked separately below; first test the playlist's views as written.
for (const park of playlist.parks) delete park.bounds;
// Alternative orders (circuit_variants) are whole view lists of their own; the player takes the
// next one on each visit, which the checks below do not follow, so they play the first order.
for (const park of playlist.parks) {
    for (const alt of park.variants ?? []) {
        assert.ok(Array.isArray(alt.views) && alt.views.length >= 3, `${park.name}: a variant lists its views`);
        assert.ok(alt.views[0].overview === park.views[0].overview, `${park.name}: a variant starts as the park does`);
    }
    delete park.variants;
}
// Generated overviews pan a little to the first close-up, changing zoom and angle on arrival.
assert.ok(playlist.parks.every(p => !p.views[0].overview || (p.views[0].pan === 0.1 && (p.views[0].panChanges ?? "end") === "end")),
    "generated overviews pan 10%, changing on arrival");
// Still views with cuts first: no pans until the pan checks at the end.
const panKeys = ["pan", "panChanges", "inertia"];
for (const park of playlist.parks) for (const v of park.views) for (const k of panKeys) delete v[k];

// Autostart: plays the sequence, first park loaded once, first view shown.
tick();
assert.deepEqual(loads, [0], "first park loads once on start");
tick();
expectView(0, 0);

// Hold times elapse -> next view, then the next park after the last view. An event view (cue)
// whose trigger never comes waits its `wait` past its hold (test/cue-run.mjs checks cues).
for (const [i, view] of playlist.parks[0].views.entries()) {
    expectView(0, i);
    tick((view.hold + (view.cue ? view.cue.wait ?? 20 : 0)) * 1000);
    tick();
}
expectView(1, 0);
assert.equal(loads.at(-1), 1);
// Sounds fade out ahead of every scheduled view change, the park's last view included, and fade in
// on every view, the new park's first view included.
{
    const outs = fades.filter(f => f.level === 0 && f.ms > 0);
    assert.equal(outs.length, playlist.parks[0].views.length, "each view of the first park fades its sounds out");
    assert.equal(outs.at(-1).loads, 1, "the last view fades out before the next park loads");
    const ins = fades.filter(f => f.level === 1 && f.ms > 0);
    assert.ok(ins.some(f => f.loads === 2), "the next park's first view fades in");
    // A key that changes park fades the sounds out before the load
    fades.length = 0;
    key("nextpark");
    assert.deepEqual(fades[0], { level: 0, ms: fades[0].ms, loads: 2 }, "a key-started park change fades out first");
    assert.ok(fades[0].ms > 0);
    tick(); tick();
    key("previouspark"); tick(); tick();
    // A key jump within a park restarts the schedule: the sounds fade in on the new view, and its
    // own fade-out comes its full hold (less the fade) later, never the old view's
    const views = playlist.parks[1].views;
    tick(views[0].hold * 1000 - 300); // inside the first view's fade-out
    assert.equal(fades.at(-1).level, 0, "the scheduled fade-out has started");
    fades.length = 0;
    key("next");
    assert.deepEqual(fades.map(f => f.level), [0, 1], "a key jump cuts and fades in");
    tick(views[1].hold * 1000 - 1000);
    assert.ok(fades.every(f => f.level !== 0 || f.ms === 0), "no early fade-out on the new view");
    tick(500);
    assert.equal(fades.at(-1).level, 0, "the new view fades out on its own schedule");
    key("previouspark"); key("nextpark"); tick(); tick();
}

// A show view (playlists/companions.toml) starts its companion's show and ends shortly after the
// companion reports the show over. The rest of this test is written for the example playlist.
const showPark = playlist.parks.findIndex(p => p.views.some(v => v.show));
if (showPark >= 0) {
    while (loads.at(-1) !== showPark) { key("nextpark"); tick(); }
    // The show plays where its showAt puts it (last by default); playlist order is play order.
    const last = playlist.parks[showPark].views.findIndex(v => v.show);
    const show = playlist.parks[showPark].views[last].show;
    const atEnd = last === playlist.parks[showPark].views.length - 1;
    for (let i = 0; i < last; i++) key("next");
    expectView(showPark, last);
    assert.equal(shows.at(-1), show.name, "showing the view starts the show");
    const view = playlist.parks[showPark].views[last];
    tick(10000);
    // Where the camera path is after `ticks` game ticks: with a pan share, one even glide through
    // its points for that share of the path's time, then the hold; else each point on schedule.
    const pathAt = ticks => {
        const len = (a, b) => Math.hypot(b.x - a.x, b.y - a.y, (b.z - a.z) / 32);
        let total = 0, length = 0, at = view;
        for (const q of view.path) { total += q.ticks; length += len(at, q); at = q; }
        const glide = view.pan ? view.pan * total : 0;
        at = view;
        for (const q of view.path) {
            const t = glide ? glide * len(at, q) / length : q.ticks;
            if (ticks < t) {
                const k = ticks / t;
                return [Math.round(at.x + (q.x - at.x) * k), Math.round(at.y + (q.y - at.y) * k)];
            }
            ticks -= t;
            at = q;
        }
        return [at.x, at.y];
    };
    if (view.path) {
        const want = pathAt(400); // 10 s is 400 game ticks
        assert.deepEqual(tileOf(), want, "the camera glides along the show's path in game ticks");
        console.log(`ok: show path at (${want}) after 400 ticks`);
    } else {
        expectView(showPark, last);
    }
    actions["rctscreensaver-showdone"]({ args: { show: show.name } });
    tick(2800);
    if (!view.path) expectView(showPark, last);
    if (view.path) {
        // A show over before the camera reaches its path's end: the view stays until it arrives
        tick(3200);
        assert.equal(loads.at(-1), showPark, "the show view stays while the camera is on its way");
        const leg = view.path.at(-1);
        assert.notDeepEqual(tileOf(), [leg.x, leg.y], "the camera is still on its way");
        const total = view.path.reduce((t, q) => t + q.ticks, 0);
        const arrival = view.pan ? view.pan * total : total;
        tick((Math.ceil(arrival) - 640) * 25 + 100); // 16 s (640 ticks) in so far
        assert.deepEqual(tileOf(), [leg.x, leg.y], "the camera reaches the path's end");
        console.log(`ok: show view stays until the camera reaches (${leg.x},${leg.y})`);
        tick(3000);
    }
    tick(400);
    if (atEnd) assert.notEqual(loads.at(-1), showPark, "the park changes shortly after the show is over");
    else expectView(showPark, last + 1);
    console.log(`ok: show "${show.name}" view, ${loads.length} park loads`);
    process.exit(0);
}

// Right/Left move through views; Left at the first view goes to the previous park's last view.
key("next"); expectView(1, 1);
key("previous"); expectView(1, 0);
key("previous"); tick(); expectView(0, playlist.parks[0].views.length - 1);
key("nextpark"); tick(); expectView(1, 0);
key("previouspark"); tick(); expectView(0, 0);

// Hold: no advance however long it waits; release restarts the hold timer.
key("nextpark"); tick();
key("hold");
tick(120000);
expectView(1, 0);
key("hold");
tick(playlist.parks[1].views[0].hold * 1000 - 200);
expectView(1, 0);
tick(200);
expectView(1, 1);

// Speed: Up/Down clamp to 1..4, persist, and survive park loads.
for (let i = 0; i < 6; i++) key("faster");
assert.equal(context.gameSpeed, 4);
assert.equal(store.RCTScreensaver.settings.speed, 4);
key("nextpark"); tick();
assert.equal(context.gameSpeed, 4, "speed is re-applied after a park load");
key("previouspark"); tick();
key("next");
for (let i = 0; i < 6; i++) key("slower");
assert.equal(context.gameSpeed, 1);
key("faster");

// Shuffle: persists, keeps the current park, and every park still plays once per cycle.
key("shuffle");
assert.equal(store.RCTScreensaver.settings.shuffle, true);
const seen = new Set([loads.at(-1)]); // the park playing when shuffle was turned on
for (let i = 1; i < playlist.parks.length; i++) { key("nextpark"); tick(); seen.add(loads.at(-1)); }
assert.equal(seen.size, playlist.parks.length, "shuffle visits every park once per cycle");

// Leaving the title screen stops the player; returning autostarts again.
context.mode = "normal"; tick();
const loadsBefore = loads.length;
context.mode = "title"; sequence.isPlaying = false; tick(); tick();
assert.ok(loads.length > loadsBefore, "autostarts again on returning to the title screen");

assert.equal(context.gameSpeed, 2, "speed is applied again after returning to the title screen");

// Fitting: on a screen larger than every park, each park gets one view at its content's centre.
const fitted = JSON.parse(fs.readFileSync(playlistPath, "utf8")).parks; // bounds only: views stay still
assert.ok(fitted.every(p => p.bounds), "playlist has bounds for every park");
playlist.parks.forEach((p, i) => { p.bounds = fitted[i].bounds; });
sandbox.ui.width = 100000; sandbox.ui.height = 100000;
store.RCTScreensaver.settings.shuffle = false;
context.mode = "normal"; tick(); context.mode = "title"; sequence.isPlaying = false; tick(); tick();
for (let i = 0; i < playlist.parks.length; i++) {
    const { bounds, views } = playlist.parks[i];
    // On screen, the overview is centred where the content is on average (all of it fits).
    const project = (x, y, z) => {
        const [a, b] = [[x, y], [y, -x], [-x, -y], [-y, x]][viewport.rotation & 3];
        return [b - a, (a + b) / 2 - z];
    };
    const [cx, cy] = project(viewport.centre.x, viewport.centre.y, viewport.centre.z);
    const [bx, by] = project(bounds.cx * 32, bounds.cy * 32, bounds.zm);
    assert.ok(Math.abs(cx - bx) <= 32 && Math.abs(cy - by) <= 32,
        `park ${i} is centred: (${cx}, ${cy}) vs (${bx}, ${by})`);
    // The view budget is spent on angles: each view turns the camera, then the next park.
    const budget = playlist.parks[i].viewCount;
    const angles = [viewport.rotation];
    for (let r = 1; r < budget; r++) { key("next"); tick(); angles.push(viewport.rotation); }
    assert.equal(new Set(angles).size, Math.min(4, budget), `park ${i} turns the angle each view: ${angles}`);
    key("next"); tick();
    assert.equal(loads.at(-1), (i + 1) % playlist.parks.length, `park ${i} has ${budget} views`);
}

// Once loaded, a small park is centred on its measured elements, not the stored box: build a
// 4x4 block in one corner of the first park and check the view centres on it.
const block = { x0: 2, y0: 3, x1: 5, y1: 6, z: 64 };
const inBlock = (x, y) => x >= block.x0 && x <= block.x1 && y >= block.y0 && y <= block.y1;
sandbox.map.getTile = (x, y) => ({ elements: [{ type: "surface", baseZ: 48 },
    ...(inBlock(x, y) ? [1, 2, 3].map(() => ({ type: "scenery", baseZ: 48, clearanceZ: 80, isHidden: false, isGhost: false })) : [])] });
key("nextpark"); tick(); while (loads.at(-1) !== 0) { key("nextpark"); tick(); }
{
    const project = (x, y, z) => {
        const [a, b] = [[x, y], [y, -x], [-x, -y], [-y, x]][viewport.rotation & 3];
        return [b - a, (a + b) / 2 - z];
    };
    const [cx, cy] = project(viewport.centre.x, viewport.centre.y, viewport.centre.z);
    // At the elements' mean height (their base, 48), as the whole block fits on screen.
    const [bx, by] = project((block.x0 + block.x1 + 1) * 16, (block.y0 + block.y1 + 1) * 16, 48);
    assert.ok(Math.abs(cx - bx) <= 8 && Math.abs(cy - by) <= 8, `centred on the built block: (${cx}, ${cy}) vs (${bx}, ${by})`);
}
sandbox.map.getTile = () => ({ elements: [{ type: "surface", baseZ: 48 }] });

// A view already inside the content on a normal screen is not moved.
sandbox.ui.width = 1920; sandbox.ui.height = 1080;
// A small park is generated like any other, with the smallest view budget, sharing the time.
{
    const tin = playlist.parks.findIndex(p => p.name === "Tin Train");
    assert.equal(playlist.parks[tin].views.length, 4, "a small park gets the base budget of views");
    while (loads.at(-1) !== tin) { key("nextpark"); tick(); }
    const shown = [];
    let last = "";
    for (let t = 0; t < 60000 && loads.at(-1) === tin; t += 100) {
        const now = `${viewport.rotation} ${viewport.zoom} ${viewport.centre.x} ${viewport.centre.y}`;
        if (now !== last) { shown.push(0); last = now; }
        shown[shown.length - 1] += 100;
        tick();
    }
    assert.equal(shown.length, playlist.parks[tin].viewCount, `small park shows its view budget: ${shown}`);
    assert.ok(Math.max(...shown) <= 15000, `no view takes most of the park's time: ${shown}`);
    while (loads.at(-1) !== tin) { key("nextpark"); tick(); }
}
const ghillie = playlist.parks.findIndex(p => p.name.startsWith("Ghillie"));
while (loads.at(-1) !== ghillie) { key("nextpark"); tick(); }
// The first view is the overview: centred where the content is and zoomed out to show all of it.
const gb = playlist.parks[ghillie].bounds;
assert.ok(playlist.parks[ghillie].views[0].overview, "generated views start with an overview");
assert.ok(Math.abs(tileOf()[0] - (gb.cx - 0.5)) <= 2 && Math.abs(tileOf()[1] - (gb.cy - 0.5)) <= 2,
    `overview is centred: ${tileOf()}`);
assert.ok(viewport.zoom >= 1, `overview zooms out: ${viewport.zoom}`);
key("next"); tick();
expectView(ghillie, 1);
assert.equal(viewport.zoom, playlist.parks[ghillie].views[1].zoom, "close-ups keep their zoom");

// View editor: pauses playback, arrows pan, edits are saved and replace the park's views.
const restart = () => { context.mode = "normal"; tick(); context.mode = "title"; sequence.isPlaying = false; tick(); tick(); };
restart();
assert.ok(playlist.parks.every(p => p.key), "playlist has a key for every park");
key("edit");
const editorWindow = windows.find(w => w.desc.classification === "rctscreensaver.editor");
assert.ok(editorWindow, "E opens the editor");
const widget = name => editorWindow.desc.widgets.find(w => w.name === name);
const click = name => widget(name).onClick();
const parkNow = loads.at(-1);
const startViews = playlist.parks[parkNow].views.length;
const centreBefore = { ...viewport.centre };
tick(120000);
assert.equal(loads.at(-1), parkNow, "no park change while editing");
assert.deepEqual({ ...viewport.centre }, centreBefore, "no view change while editing");
// Selecting a view saves nothing: only a real change pins the park's views.
editorWindow.desc.widgets.find(w => w.name === "views").onClick(0);
assert.ok(!(playlist.parks[parkNow].key in (store.RCTScreensaver.edits ?? {})), "selecting a view saves no edit");
key("next"); // pans right instead of changing view
assert.notDeepEqual({ ...viewport.centre }, centreBefore, "arrows pan the camera");
const panned = { ...viewport.centre };
click("add");
const edits = () => store.RCTScreensaver.edits[playlist.parks[parkNow].key].views;
assert.equal(edits().length, editorWindow.widgets.views.items.length, "list shows the edited views");
const added = edits().findIndex(v => Math.abs(v.x * 32 + 16 - panned.x) < 1 && Math.abs(v.y * 32 + 16 - panned.y) < 1);
assert.ok(added >= 0, "Add saves the camera position");
assert.equal(JSON.stringify(store.RCTScreensaver.edits[playlist.parks[parkNow].key].screen), "[1920,1080]", "edits keep the window they were set in");
assert.deepEqual({ ...editorWindow.widgets.views.selectedCell }, { row: added, column: 0 });
assert.ok(!store.RCTScreensaver.edits[playlist.parks[parkNow].key].arranged, "adding a view is not a rearrangement");
click("up");
assert.ok(store.RCTScreensaver.edits[playlist.parks[parkNow].key].arranged, "Move up marks the list as arranged");
assert.ok(Math.abs(edits()[Math.max(0, added - 1)].x * 32 + 16 - panned.x) < 1, "Move up reorders");
const sel = editorWindow.widgets.views.selectedCell.row;
const hold = edits()[sel].hold;
widget("hold").onIncrement();
assert.equal(edits()[sel].hold, Math.round(hold) + 1, "spinner changes the hold");
click("rotr");
assert.equal(viewport.rotation, (edits()[sel].rotation + 1) % 4);
click("update");
assert.equal(edits()[sel].rotation, viewport.rotation, "Set to camera updates the view");
click("delete");
assert.equal(edits().length, editorWindow.widgets.views.items.length);
const count = edits().length;
// Play: the park's views play on in the editor, looping in the park; an edit plays on again
// from the selected view a second later; moving the camera stops it.
{
    const selRow = editorWindow.widgets.views.selectedCell.row;
    const at = i => Math.abs(viewport.centre.x - Math.round(edits()[i].x * 32 + 16)) < 1
        && Math.abs(viewport.centre.y - Math.round(edits()[i].y * 32 + 16)) < 1
        && viewport.rotation === edits()[i].rotation && viewport.zoom === edits()[i].zoom;
    click("play");
    assert.ok(editorWindow.widgets.play.isPressed, "Play is on");
    assert.ok(at(selRow), "Play starts from the selected view");
    tick(edits()[selRow].hold * 1000 + 1300);
    assert.ok(!at(selRow) && at((selRow + 1) % count), "then moves on after a second's wait and the hold");
    assert.equal(editorWindow.widgets.views.selectedCell.row, (selRow + 1) % count, "the list highlights the view on screen");
    const total = edits().reduce((t, v) => t + v.hold, 0);
    tick(total * 2000 + 3000);
    assert.equal(loads.at(-1), parkNow, "Play never changes the park");
    editorWindow.desc.widgets.find(w => w.name === "views").onClick(selRow);
    widget("hold").onIncrement();
    assert.ok(at(selRow), "an edit shows the selected view again");
    tick(edits()[selRow].hold * 1000 + 500);
    assert.ok(at(selRow), "and plays on only a second after the edit");
    tick(800);
    assert.ok(!at(selRow), "then moves on");
    editorWindow.desc.widgets.find(w => w.name === "views").onClick(selRow);
    widget("hold").onDecrement();
    key("next"); // the arrow moves the camera by hand: Play stops
    assert.ok(!editorWindow.widgets.play.isPressed, "moving the camera stops Play");
    const still = { ...viewport.centre };
    tick(total * 1000 + 1000);
    assert.deepEqual({ ...viewport.centre }, still, "and nothing moves after that");
}
widget("park").onChange((parkNow + 2) % playlist.parks.length);
tick(); tick();
assert.equal(loads.at(-1), (parkNow + 2) % playlist.parks.length, "the park picker loads a park");
key("edit");
assert.ok(!windows.includes(editorWindow), "E closes the editor");
// Back on the edited park, its hand-set views play exactly, in order.
while (loads.at(-1) !== parkNow) { key("nextpark"); tick(); }
for (let i = 0; i < count; i++) {
    const v = edits()[i];
    assert.ok(Math.abs(viewport.centre.x - Math.round(v.x * 32 + 16)) < 1, `edited view ${i} plays as set`);
    tick(v.hold * 1000); tick();
}
assert.notEqual(loads.at(-1), parkNow, "moves on after the edited views");
// Use playlist views drops the edit.
while (loads.at(-1) !== parkNow) { key("nextpark"); tick(); }
key("edit");
windows.find(w => w.desc.classification === "rctscreensaver.editor").desc.widgets.find(w => w.name === "revert").onClick();
assert.ok(!(playlist.parks[parkNow].key in store.RCTScreensaver.edits), "revert removes the edit");
key("edit");
assert.ok(startViews > 0);
// A park whose views came from the views file resets to its playlist views, marked for install.
{
    const park = playlist.parks[parkNow];
    const handView = { x: 3, y: 4, z: 40, rotation: 1, zoom: -1, hold: 5, manual: true };
    Object.assign(park, { handSet: true, defaultViews: park.views, views: [handView] });
    restart();
    while (loads.at(-1) !== parkNow) { key("nextpark"); tick(); }
    assert.deepEqual(tileOf(), [3, 4], "hand-set views from the file play as set");
    key("edit");
    windows.find(w => w.desc.classification === "rctscreensaver.editor").desc.widgets.find(w => w.name === "revert").onClick();
    assert.equal(store.RCTScreensaver.edits[park.key].reset, true, "reset is saved for the installer");
    assert.notDeepEqual(tileOf(), [3, 4], "playlist views play after the reset");
    key("edit");
    Object.assign(park, { handSet: undefined, views: park.defaultViews, defaultViews: undefined });
    delete store.RCTScreensaver.edits[park.key];
}

// Panning views: a view with a pan share spends the end of its hold panning to the next view,
// arriving as its hold starts. Everything above ran with no pan (held still, then a cut).
{
    const park = playlist.parks[0];
    const panViews = [
        { x: 10, y: 10, z: 48, rotation: 0, zoom: -1, hold: 10, pan: 0.5 },
        { x: 14, y: 12, z: 48, rotation: 0, zoom: -1, hold: 10, pan: 1 },
        { x: 14, y: 12, z: 48, rotation: 1, zoom: 0, hold: 10, pan: 0.5, panChanges: "start" }, // same spot as before: a cut
        { x: 20, y: 30, z: 64, rotation: 2, zoom: -1, hold: 10, pan: 0.5 },
        { x: 70, y: 70, z: 64, rotation: 0, zoom: -1, hold: 10, pan: 0.9 }, // far, opposite angle
        { x: 72, y: 71, z: 64, rotation: 0, zoom: -1, hold: 10 },
    ];
    Object.assign(park, { handSet: true, defaultViews: park.views, views: panViews });
    restart();
    while (loads.at(-1) !== 0) { key("nextpark"); tick(); }
    const centre = () => `${Math.round(viewport.centre.x)},${Math.round(viewport.centre.y)}`;
    const at = v => centre() === `${v.x * 32 + 16},${v.y * 32 + 16}` && viewport.rotation === v.rotation && viewport.zoom === v.zoom;
    // Runs until `done` (at most `ms`), returning how long it took.
    const until = (done, ms = 20000) => { let t = 0; while (!done() && t < ms) { tick(); t += 100; } return t; };
    assert.ok(at(panViews[0]), "a park's first view is shown at once");
    fades.length = 0;
    tick(4900);
    assert.ok(at(panViews[0]), "still for the first half of the hold");
    const centres = new Set();
    for (let t = 0; t < 4900; t += 100) {
        tick();
        centres.add(centre());
        if (t === 2400) { // no inertia: one speed, so halfway through the pan, halfway there
            assert.ok(Math.abs(viewport.centre.x - (12 * 32 + 16)) <= 2 && Math.abs(viewport.centre.y - (11 * 32 + 16)) <= 2,
                `linear pan is halfway: ${centre()}`);
        }
        assert.equal(viewport.zoom, -1); assert.equal(viewport.rotation, 0);
    }
    assert.ok(centres.size > 20, `the camera pans smoothly: ${centres.size} positions`);
    assert.ok(!fades.some(f => f.level === 0), "a pan keeps the sounds");
    tick(200);
    assert.ok(at(panViews[1]), "the pan arrives on the next view as its hold starts");
    // A view with no distance to the next cuts, with the sounds fading out ahead of it as before.
    tick(9600);
    assert.ok(fades.some(f => f.level === 0 && f.ms > 0), "sounds fade out before a cut");
    tick(300);
    assert.ok(at(panViews[2]), "same spot from another angle: a cut");
    // "start": angle and zoom change as the pan sets off and the camera stays there 2 s (time
    // added to the view), then moves at the next view's zoom (within the speed tolerance there).
    tick(5000);
    assert.equal(viewport.rotation, 2, "the angle turns as the pan sets off");
    assert.equal(viewport.zoom, -1, "and the zoom changes with it");
    const turnedAt = centre();
    tick(1700);
    assert.equal(centre(), turnedAt, "the camera stays a moment after the change");
    tick(1000);
    assert.notEqual(centre(), turnedAt, "then moves");
    // Holding pauses the pan where it is; releasing carries on.
    key("hold");
    const heldAt = centre();
    tick(5000);
    assert.equal(centre(), heldAt, "holding stops the pan");
    key("hold");
    const arrival = until(() => at(panViews[3]));
    assert.ok(arrival > 4000 && arrival < 6000, `and arrives after the added time and the 1 s rest before zooming in: ${arrival} ms`);
    // Opposite angles turn one step as the pan sets off and one on arrival; the far pan at one
    // zoom travels zoomed out.
    tick(5000);
    assert.equal(viewport.rotation, 3, "first turn as the pan sets off");
    const travel = viewport.zoom;
    assert.ok(travel > -1, `a far pan at one zoom travels zoomed out: ${travel}`);
    until(() => viewport.rotation === 0 && viewport.zoom === -1);
    assert.ok(at(panViews[4]), "second turn and zoom back in on arrival");
    // A view whose angle changed on arrival stays still at least 2 s before panning on, though its
    // own still share is 1 s: the second is added to its hold.
    tick(1800);
    assert.ok(at(panViews[4]), "still for 2 s after the change");
    tick(500);
    assert.ok(!at(panViews[4]), "then pans on");
    const rest = until(() => at(panViews[5]));
    assert.ok(rest > 8000 && rest < 9500, `the pan keeps its full time: ${rest} ms`);
    // Keys cut straight to a view.
    key("previous");
    assert.ok(at(panViews[4]), "Left cuts to the previous view");
    // In a playlist of several parks the last view pans back to the first too: to a wider first
    // view it steps one zoom out as it sets off (moving at once), steps further out mid-pan, turns on arrival after
    // a 1 s rest, holds 2 s at the first view, and the next park follows.
    {
        const firstView = { ...panViews[0] };
        Object.assign(panViews[0], { rotation: 2, zoom: 1 });
        panViews[5].pan = 0.5;
        restart();
        while (loads.at(-1) !== 0) { key("nextpark"); tick(); }
        const loaded = loads.length;
        for (let i = 0; i < 5; i++) key("next"); // keys cut: to the last view
        assert.ok(at(panViews[5]), "on the last view");
        tick(5100);
        assert.equal(viewport.rotation, 0, "keeps its angle as it sets off");
        assert.equal(viewport.zoom, 0, "and steps one zoom out");
        const setOff = centre();
        tick(500);
        assert.notEqual(centre(), setOff, "and moves at once");
        until(() => viewport.zoom === 1);
        assert.ok(!at(panViews[0]) && centre() !== setOff, "steps further out mid-pan");
        const arrival = until(() => at(panViews[0]) || loads.length > loaded);
        assert.ok(at(panViews[0]), `arrives at the first view: ${arrival} ms`);
        tick(1800);
        assert.equal(loads.length, loaded, "holds there 2 s");
        until(() => loads.length > loaded, 3000);
        assert.ok(loads.length > loaded, "then the next park loads");
        delete panViews[5].pan;
        Object.assign(panViews[0], firstView);
    }
    // The playlist's return hold (settings UI) replaces the plugin setting's 2 s.
    {
        panViews[5].pan = 0.5;
        playlist.returnHold = 4;
        restart();
        while (loads.at(-1) !== 0) { key("nextpark"); tick(); }
        const loaded = loads.length;
        for (let i = 0; i < 5; i++) key("next");
        until(() => at(panViews[0]) || loads.length > loaded);
        assert.ok(at(panViews[0]), "the return pan arrives");
        tick(3800);
        assert.equal(loads.length, loaded, "holds there the playlist's 4 s");
        until(() => loads.length > loaded, 3000);
        assert.ok(loads.length > loaded, "then the next park loads");
        delete playlist.returnHold;
        delete panViews[5].pan;
    }
    // returnPan = false: the last view holds still and cuts to the next park.
    {
        panViews[5].pan = 0.5;
        park.returnPan = false;
        restart();
        while (loads.at(-1) !== 0) { key("nextpark"); tick(); }
        const loaded = loads.length;
        for (let i = 0; i < 5; i++) key("next");
        assert.ok(at(panViews[5]), "on the last view");
        const left = until(() => !at(panViews[5]) || loads.length > loaded, 60000);
        assert.ok(loads.length > loaded, `no return pan: the next park follows the still view (${left} ms)`);
        delete park.returnPan;
        delete panViews[5].pan;
    }
    // A park playing alone loops, panning from its last view back to its first.
    {
        const allParks = playlist.parks;
        playlist.parks = [park];
        panViews[5].pan = 0.5;
        restart();
        const loaded = loads.length;
        key("previous"); // to the last view
        assert.ok(at(panViews[5]), "the last view");
        tick(5100);
        assert.ok(!at(panViews[5]) && !at(panViews[0]), "pans on after its still half");
        until(() => at(panViews[0]));
        assert.ok(at(panViews[0]), "back to the first view");
        assert.equal(loads.length, loaded, "without reloading the park");
        delete panViews[5].pan;
        playlist.parks = allParks;
        restart();
    }
    Object.assign(park, { handSet: undefined, views: park.defaultViews, defaultViews: undefined });
}

// Window scaling: views framed for a larger screen play whole zoom levels out, so this window
// shows what they were framed for, and pans are held to a tolerance halved with the window.
{
    playlist.screen = [3840, 2160];
    store.RCTScreensaver.settings.cameraLog = true;
    restart();
    const park = playlist.parks.findIndex(p => p.name.startsWith("Ghillie"));
    while (loads.at(-1) !== park) { key("nextpark"); tick(); }
    key("next"); tick();
    const view = playlist.parks[park].views[1];
    assert.equal(viewport.zoom, Math.min(3, view.zoom + 1), "a close-up framed for 3840x2160 plays a zoom level out");
    assert.ok(logs.some(l => l.includes("screen window=1920x1080 design=3840x2160 offset=1 scale=0.5")), "the camera log names the scaling");
    // Edits set in a larger window play a level out here too; those set in this window as set.
    const key0 = playlist.parks[park].key;
    store.RCTScreensaver.edits = { [key0]: { views: [{ ...view, hold: 5 }], screen: [3840, 2160] } };
    restart();
    while (loads.at(-1) !== park) { key("nextpark"); tick(); }
    assert.equal(viewport.zoom, Math.min(3, view.zoom + 1), "an edit from a 3840x2160 window plays a level out");
    store.RCTScreensaver.edits = { [key0]: { views: [{ ...view, hold: 5 }], screen: [1920, 1080] } };
    restart();
    while (loads.at(-1) !== park) { key("nextpark"); tick(); }
    assert.equal(viewport.zoom, view.zoom, "an edit from this window plays as set");
    // The setting turns it off.
    delete store.RCTScreensaver.edits;
    store.RCTScreensaver.settings.scaleToWindow = false;
    restart();
    while (loads.at(-1) !== park) { key("nextpark"); tick(); }
    key("next"); tick();
    assert.equal(viewport.zoom, view.zoom, "scaleToWindow off plays the zooms as framed");
    store.RCTScreensaver.settings.scaleToWindow = true;
    store.RCTScreensaver.settings.cameraLog = false;
    playlist.screen = [1920, 1080];
}

console.log(`ok: ${loads.length} park loads, ${logs.length} log lines`);
